content:
#!/usr/bin/env bash
# PreToolUse hook for Bash: blocks recursive forced deletes (rm -rf and variants).
# Reads the hook event JSON on stdin. Exit 2 blocks the call; stderr is the reason.
# Fails closed: if the check itself cannot run, the command is blocked.

command -v python3 >/dev/null 2>&1 || {
  echo "block-rm: python3 not found, cannot verify the command is safe" >&2
  exit 2
}

input=$(cat)

printf '%s' "$input" | python3 -c "
import json, os, re, shlex, sys

SEP = re.compile(r'[;&|()\n\`]|\\$\\(')
SHELLS = {'sh', 'bash', 'zsh', 'dash', 'ksh', 'eval'}

def is_rm(tok):
    return os.path.basename(tok) == 'rm'

def forced_recursive(args):
    recursive = force = False
    for a in args:
        if a == '--':
            break
        if a == '--recursive':
            recursive = True
        elif a == '--force':
            force = True
        elif a.startswith('--'):
            continue
        elif a.startswith('-'):
            if 'r' in a[1:] or 'R' in a[1:]:
                recursive = True
            if 'f' in a[1:]:
                force = True
    return recursive and force

def dangerous(cmd, depth=0):
    if depth > 5:
        return False
    for seg in SEP.split(cmd):
        try:
            toks = shlex.split(seg)
        except ValueError:
            toks = seg.split()
        for i, t in enumerate(toks):
            if is_rm(t) and forced_recursive(toks[i + 1:]):
                return True
            # Re-check the payload of sh -c / eval, e.g. bash -c \"rm -rf x\"
            if any(os.path.basename(p) in SHELLS for p in toks[:i]) and any(c.isspace() for c in t):
                if dangerous(t, depth + 1):
                    return True
    return False

try:
    data = json.load(sys.stdin)
    if data.get('tool_name') != 'Bash':
        sys.exit(0)
    cmd = (data.get('tool_input') or {}).get('command', '') or ''
    blocked = dangerous(cmd)
except SystemExit:
    raise
except Exception as e:
    sys.stderr.write('block-rm: could not check command (%s), blocking to be safe\n' % e)
    sys.exit(2)

if blocked:
    sys.stderr.write('Blocked: rm -rf (recursive + forced delete, including variants) is not allowed in this project. Delete specific files by name instead, or ask the user to run it themselves.\n')
    sys.exit(2)
sys.exit(0)
"

