#!/usr/bin/env bash
# PreToolUse gate: block any rm invocation that is both recursive and forced.
# Reads the hook event JSON on stdin. Exit 2 blocks the call; stderr goes to Claude.
set -u

command -v jq >/dev/null 2>&1 || {
  echo "block-rm: jq is not installed, so the command cannot be checked; blocking to be safe." >&2
  exit 2
}

cmd=$(jq -r '.tool_input.command // empty') || exit 2
[ -z "$cmd" ] && exit 0

# Split on shell separators so each simple command is checked on its own.
segments=$(printf '%s\n' "$cmd" | sed -e 's/[;&|()`]/\n/g')

while IFS= read -r seg; do
  read -r -a words <<< "$seg"
  for i in "${!words[@]}"; do
    w=${words[$i]//[\"\']/}
