    recursive=0
    force=0
    for ((j = i + 1; j < ${#words[@]}; j++)); do
      f=${words[$j]//[\"\']/}
      case $f in
        --) break ;;
        --recursive) recursive=1 ;;
        --force) force=1 ;;
        --*) ;;
        -*)
          [[ $f == *[rR]* ]] && recursive=1
          [[ $f == *f* ]] && force=1
          ;;
      esac
    done

    if (( recursive && force )); then
      echo "Blocked: rm -rf (recursive + force) is not allowed in this project. Remove specific files by name, or ask the user to run the command themselves." >&2
      exit 2
    fi
  done
done <<< "$segments"

exit 0
