const { test } = require("node:test");
const assert = require("node:assert");
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const gate = path.join(__dirname, "..", "hooks", "stop-gate.sh");

// Build a throwaway project whose `npm test` exits with the given code.
function makeProject(testExitCode) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "stop-gate-"));
  fs.writeFileSync(
    path.join(dir, "package.json"),
    JSON.stringify({
      name: "fixture",
      version: "0.0.0",
      scripts: { test: `node -e "console.log('suite ran'); process.exit(${testExitCode})"` },
    })
  );
  return dir;
}

function runGate(cwd) {
  return spawnSync("bash", [gate], {
    input: JSON.stringify({ hook_event_name: "Stop", stop_hook_active: false, cwd }),
    encoding: "utf8",
  });
}

test("blocks the stop (exit 2) when npm test fails", () => {
  const dir = makeProject(1);
  const result = runGate(dir);
  assert.strictEqual(result.status, 2);
  assert.match(result.stderr, /npm test is failing/);
  assert.match(result.stderr, /suite ran/);
});

test("allows the stop (exit 0) when npm test passes", () => {
  const dir = makeProject(0);
  const result = runGate(dir);
  assert.strictEqual(result.status, 0);
});

test("allows the stop when the project has no test script", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "stop-gate-"));
  fs.writeFileSync(path.join(dir, "package.json"), JSON.stringify({ name: "fixture" }));
  const result = runGate(dir);
  assert.strictEqual(result.status, 0);
});

